# Fingerprints every clip in raccoon_v2.glb: length, step, loop mode, and every track's
# type, path, interpolation and keys (times and values), SHA-256'd per clip. Also prints
# jump's key times and the hind-leg bones' rotations at frames 0 and 3.

func _find_player(n: Node) -> AnimationPlayer:
	if n is AnimationPlayer:
		return n
	for c in n.get_children():
		var p := _find_player(c)
		if p:
			return p
	return null

func _initialize() -> void:
	var root: Node = load("res://assets/characters/raccoon_v2.glb").instantiate()
	var ap := _find_player(root)
	var names := ap.get_animation_list()
	for name in names:
		var a: Animation = ap.get_animation(name)
		var s := "len=%s step=%s loop=%d tracks=%d\n" % [var_to_str(a.length), var_to_str(a.step), a.loop_mode, a.get_track_count()]
		var times := {}
		for t in a.get_track_count():
			s += "%d %s %d %d\n" % [a.track_get_type(t), str(a.track_get_path(t)), a.track_get_interpolation_type(t), a.track_get_key_count(t)]
			for k in a.track_get_key_count(t):
				var kt := a.track_get_key_time(t, k)
				times[snappedf(kt * 24.0, 0.001)] = true
				s += "%s=%s\n" % [var_to_str(kt), var_to_str(a.track_get_key_value(t, k))]
		print("CLIP %-10s len %.6f (%.3f frames) step %.6f loop %d tracks %d sha256 %s" % [
			name, a.length, a.length * 24.0, a.step, a.loop_mode, a.get_track_count(), s.sha256_text()])
		if name == "jump":
			var ks := times.keys()
			ks.sort()
			print("  jump key frames (time*24): ", ks)
			for bone in ["thigh.L", "shin.L", "foot.L", "thigh.R", "shin.R", "foot.R", "pelvis"]:
				for t in a.get_track_count():
					var p := str(a.track_get_path(t))
					if p.ends_with(":" + bone) and a.track_get_type(t) == Animation.TYPE_ROTATION_3D:
						for f in [0, 3]:
							var q: Quaternion = a.rotation_track_interpolate(t, f / 24.0)
							var e := q.get_euler() * (180.0 / PI)
							print("  %-8s frame %d  quat (%.4f, %.4f, %.4f, %.4f)  euler deg (%.1f, %.1f, %.1f)" % [
								bone, f, q.x, q.y, q.z, q.w, e.x, e.y, e.z])
	root.free()
	quit()

