				line.append("%.1f" % (rad_to_deg(2.0 * acos(clampf(q3.w, -1, 1))) * signf(q3.x if q3.x != 0 else 1.0)))
			print("  sampled frames 0-10: ", ", ".join(line))
	root.free()
	quit()
